import*as THREE from"three";
import{DISCLAIMER,encodeImageBytes}from"./exportView";
export const SLAB_HALF_THICKNESS=0.055;
export type SectionPlaneName="axial"|"front";
export interface SlicePlane{readonly name:SectionPlaneName;readonly normal:THREE.Vector3;readonly vertical:THREE.Vector3;readonly cameraUp:1|-1;}
export const AXIAL_PLANE:SlicePlane={name:"axial",normal:new THREE.Vector3(0,1,0),vertical:new THREE.Vector3(0,0,1),cameraUp:-1};
export const FRONT_PLANE:SlicePlane={name:"front",normal:new THREE.Vector3(0,0,1),vertical:new THREE.Vector3(0,1,0),cameraUp:1};
export function depthLabel(metresIn:number):string{return`${Math.max(0,Math.round(metresIn*100))} cm deep`;}
export function slicePlane(name:SectionPlaneName):SlicePlane{return name==="front"?FRONT_PLANE:AXIAL_PLANE;}
export function planePoint(plane:SlicePlane,h:number,v:number,at:number):THREE.Vector3{return new THREE.Vector3(h,0,0).addScaledVector(plane.vertical,v).addScaledVector(plane.normal,at);}
export function cameraUpOf(plane:SlicePlane):THREE.Vector3{return plane.vertical.clone().multiplyScalar(plane.cameraUp);}
export function cameraForwardOf(plane:SlicePlane):THREE.Vector3{return plane.normal.clone().negate();}
export function slabPlanes(plane:SlicePlane,at:number,half=SLAB_HALF_THICKNESS):THREE.Plane[]{return[new THREE.Plane(plane.normal.clone().negate(),at+half),new THREE.Plane(plane.normal.clone(),half-at)];}
export function cutPlanes(plane:SlicePlane,at:number):THREE.Plane[]{return[new THREE.Plane(plane.normal.clone().negate(),at)];}
export const SLICE_MIN_HALF=0.05;
export function sliceWindowOf(box:THREE.Box3,plane:SlicePlane,margin=1.06):SliceWindow{const centre=box.getCenter(new THREE.Vector3());const size=box.getSize(new THREE.Vector3());const half=Math.max(Math.max(size.x,size.dot(plane.vertical))/2*margin,SLICE_MIN_HALF);return{h:centre.x,v:centre.dot(plane.vertical),half};}
export const SLICE_UP=cameraUpOf(AXIAL_PLANE);
export interface SliceBasis{right:1|-1;down:1|-1;}
export function sliceBasis(leftSign:1|-1):SliceBasis{return{right:leftSign,down:-1};}
export const SLICE_FORWARD=cameraForwardOf(AXIAL_PLANE);
export const SLICE_PIXELS_NORMAL=2048;
export const SLICE_PIXELS_HIGH=4096;
export function sliceSize(high:boolean,maxTexture:number):number{const wanted=high?SLICE_PIXELS_HIGH:SLICE_PIXELS_NORMAL;if(!(maxTexture>0))return SLICE_PIXELS_NORMAL;return Math.min(wanted,maxTexture);}
export const SLICE_PIXELS={value:SLICE_PIXELS_NORMAL};
export interface SliceWindow{h:number;v:number;half:number;}
export const SECTION_VIEW:{value:SliceWindow|null;}={value:null};
export const MIN_SECTION_HALF_M=0.03;
export function zoomWindow(frame:SliceWindow,base:SliceWindow,by:number,basis:SliceBasis,u=0,v=0):SliceWindow|null{if(!(by>0)||!(base.half>0))return SECTION_VIEW.value;const half=clamp(frame.half/by,MIN_SECTION_HALF_M,base.half);if(half>=base.half)return null;const anchorH=frame.h+basis.right*u*frame.half;const anchorV=frame.v+basis.down*v*frame.half;return inside({h:anchorH-basis.right*u*half,v:anchorV-basis.down*v*half,half},base);}
export function panWindow(frame:SliceWindow,base:SliceWindow,dxPx:number,dyPx:number,windowPx:number,basis:SliceBasis):SliceWindow|null{if(!(windowPx>0))return SECTION_VIEW.value;const travel=2*frame.half/windowPx;return inside({h:frame.h-basis.right*dxPx*travel,v:frame.v-basis.down*dyPx*travel,half:frame.half},base);}
function inside(window:SliceWindow,base:SliceWindow):SliceWindow{const reach=Math.max(0,base.half-window.half);return{h:clamp(window.h,base.h-reach,base.h+reach),v:clamp(window.v,base.v-reach,base.v+reach),half:window.half};}
function clamp(value:number,low:number,high:number):number{return Math.max(low,Math.min(high,value));}
export interface SectionMeasure{ah:number;av:number;bh:number;bv:number;at:number;plane:SectionPlaneName;}
export const MEASURE_LEVEL_TOLERANCE_M=0.005;
export function onLevel(line:Pick<SectionMeasure,"at"|"plane">,at:number,plane:SectionPlaneName):boolean{return line.plane===plane&&Math.abs(line.at-at)<=MEASURE_LEVEL_TOLERANCE_M;}
export function pointInSection(window:SliceWindow,offsetXPx:number,offsetYPx:number,windowPx:number,basis:SliceBasis):{h:number;v:number;}{const across=2*window.half/windowPx;return{h:window.h+basis.right*(offsetXPx-windowPx/2)*across,v:window.v+basis.down*(offsetYPx-windowPx/2)*across};}
export function pointOnScreen(window:SliceWindow,h:number,v:number,windowPx:number,basis:SliceBasis):{x:number;y:number;}{if(!(window.half>0))return{x:0,y:0};const perMetre=windowPx/(2*window.half);return{x:windowPx/2+basis.right*(h-window.h)*perMetre,y:windowPx/2+basis.down*(v-window.v)*perMetre};}
export function measureCm(line:Pick<SectionMeasure,"ah"|"av"|"bh"|"bv">):number{return Math.hypot(line.bh-line.ah,line.bv-line.av)*100;}
export function formatDistance(cm:number):string{if(!(cm>0))return"";if(cm<1)return`${Math.round(cm*10)} mm`;return`${cm.toFixed(1)} cm`;}
export async function sectionImage(window:SliceWindow,lines:readonly SectionMeasure[],basis:SliceBasis):Promise<string|null>{const source=AXIAL_CANVAS.value;if(!source||source.width===0)return null;const size=source.width;const canvas=document.createElement("canvas");canvas.width=size;canvas.height=size;const context=canvas.getContext("2d");if(!context)return null;context.drawImage(source,0,0);if(window.half>0)for(const line of lines)drawMeasure(context,line,window,size,basis);const blob=await new Promise<Blob|null>(resolve=>canvas.toBlob(resolve,"image/png"));if(!blob)return null;return encodeImageBytes(new Uint8Array(await blob.arrayBuffer()));}
function drawMeasure(context:CanvasRenderingContext2D,line:SectionMeasure,window:SliceWindow,size:number,basis:SliceBasis):void{const a=pointOnScreen(window,line.ah,line.av,size,basis);const b=pointOnScreen(window,line.bh,line.bv,size,basis);context.strokeStyle="#22d3ee";context.lineWidth=Math.max(2,size/512);context.beginPath();context.moveTo(a.x,a.y);context.lineTo(b.x,b.y);context.stroke();const dot=Math.max(3,size/340);context.fillStyle="#22d3ee";for(const end of[a,b]){context.beginPath();context.arc(end.x,end.y,dot,0,Math.PI*2);context.fill();}const label=formatDistance(measureCm(line));if(!label)return;const type=Math.round(size/42);context.font=`${type}px system-ui, "Segoe UI", sans-serif`;context.textBaseline="alphabetic";context.textAlign="left";context.lineWidth=Math.max(3,type/5);context.strokeStyle="rgba(2, 6, 23, 0.9)";context.fillStyle="#a5f3fc";const x=(a.x+b.x)/2+type*0.6;const y=(a.y+b.y)/2-type*0.6;context.strokeText(label,x,y);context.fillText(label,x,y);}
export function sectionFileName(plane:SectionPlaneName,where:string|null,acrossCm:number,cut:boolean):string{const parts=["anatria3d",plane];const named=where?.replace(/[^A-Za-z0-9]+/g,"-").replace(/^-|-$/g,"");if(named)parts.push(named);if(acrossCm>0)parts.push(`${Math.round(acrossCm)}cm`);parts.push(cut?"cut":"slab");return`${parts.join("-")}.png`;}
export const SECTION_WINDOW="min(90vh, calc(100vw - 23rem))";
export const SECTION_WANTED={value:0};
export function wantSection():void{SECTION_WANTED.value+=1;}
export const WHEEL_PER_STEP=100;
export function wheelPixels(deltaY:number,deltaMode:number):number{if(deltaMode===1||deltaMode===2)return Math.sign(deltaY)*WHEEL_PER_STEP;return deltaY;}
export function wheelSteps(carried:number,deltaY:number,perStep:number=WHEEL_PER_STEP):{steps:number;carry:number;}{const reversed=carried!==0&&deltaY!==0&&carried>0!==deltaY>0;const total=reversed?deltaY:carried+deltaY;const steps=Math.trunc(total/perStep);return{steps,carry:total-steps*perStep};}
export const WHEEL_SETTLE_MS=130;
const TORCH_LOWEST=8*Math.PI/180;
export function torchDirection(u:number,v:number,basis:SliceBasis,plane:SlicePlane):THREE.Vector3{const reach=Math.min(1,Math.hypot(u,v));const overhead=plane.normal.clone();if(reach<1e-6)return overhead;const towards=new THREE.Vector3(basis.right*u,0,0).addScaledVector(plane.vertical,basis.down*v).normalize();const above=TORCH_LOWEST+(1-reach)*(Math.PI/2-TORCH_LOWEST);return towards.multiplyScalar(Math.cos(above)).addScaledVector(overhead,Math.sin(above)).normalize();}
export const TORCH:{value:THREE.Vector3|null;}={value:null};
export const RETAKE_INTERVAL_MS=35;
export const AXIAL_CANVAS:{value:HTMLCanvasElement|null;}={value:null};
export interface SlicePathologyOverlay{active:boolean;pathologyId?:string;scanKind?:"cxr"|"chest_ct"|"neuro_ct"|"echo"|"abdo_us";code:string;label:string;shortLabel?:string;cx:number;cy:number;relX?:number;relY?:number;liveProgress?:number;scanAt?:number;radius:number;appearance:"hyperdense"|"hypodense"|"mixed"|"dark_fluid_hemorrhage";}
export const SLICE_PATHOLOGY_OVERLAY:{value:SlicePathologyOverlay|null;}={value:null};
export function paintSlice(canvas:HTMLCanvasElement,pixels:Uint8Array,size:number,basis:SliceBasis,plane:SlicePlane):void{fit(canvas,size);const context=canvas.getContext("2d");if(!context)return;const image=context.createImageData(size,size);const row=size*4;const flip=plane.cameraUp!==basis.down;const mirror=basis.right===-1;const from32=mirror?new Uint32Array(pixels.buffer,pixels.byteOffset,size*size):null;const to32=mirror?new Uint32Array(image.data.buffer,image.data.byteOffset,size*size):null;for(let y=0;y<size;y++){const source=flip?size-1-y:y;if(!from32||!to32){image.data.set(pixels.subarray(source*row,source*row+row),y*row);continue;}const src=source*size;const dst=y*size;for(let x=0;x<size;x++)to32[dst+x]=from32[src+size-1-x]!;}const data=image.data;const srcCopy=new Uint8ClampedArray(data);const maskMap=new Uint8Array(size*size);let minX=size;let maxX=0;let minY=size;let maxY=0;let sumX=0;let sumY=0;let tissueCount=0;for(let y=0;y<size;y++){const rowOff=y*size;for(let x=0;x<size;x++){const pIdx=rowOff+x;const i=pIdx*4;const r=srcCopy[i]!;const g=srcCopy[i+1]!;const b=srcCopy[i+2]!;const a=srcCopy[i+3]!;const isDarkBg=a<16||r<=14&&g<=18&&b<=34||Math.abs(r-27)<=7&&Math.abs(g-25)<=7&&Math.abs(b-23)<=7;if(isDarkBg){data[i]=7;data[i+1]=10;data[i+2]=16;data[i+3]=255;maskMap[pIdx]=0;continue;}maskMap[pIdx]=1;if(x<minX)minX=x;if(x>maxX)maxX=x;if(y<minY)minY=y;if(y>maxY)maxY=y;sumX+=x;sumY+=y;tissueCount+=1;}}for(let y=1;y<size-1;y++){const rowOff=y*size;for(let x=1;x<size-1;x++){const pIdx=rowOff+x;if(maskMap[pIdx]===0)continue;const i=pIdx*4;const r=srcCopy[i]!;const g=srcCopy[i+1]!;const b=srcCopy[i+2]!;const nTop=((y-1)*size+x)*4;const nBot=((y+1)*size+x)*4;const nLeft=(rowOff+(x-1))*4;const nRight=(rowOff+(x+1))*4;const avgR=(srcCopy[nTop]!+srcCopy[nBot]!+srcCopy[nLeft]!+srcCopy[nRight]!)*0.25;const avgG=(srcCopy[nTop+1]!+srcCopy[nBot+1]!+srcCopy[nLeft+1]!+srcCopy[nRight+1]!)*0.25;const avgB=(srcCopy[nTop+2]!+srcCopy[nBot+2]!+srcCopy[nLeft+2]!+srcCopy[nRight+2]!)*0.25;let sr=r+(r-avgR)*0.65;let sg=g+(g-avgG)*0.65;let sb=b+(b-avgB)*0.65;const lum=0.299*sr+0.587*sg+0.114*sb;const boostedLum=Math.min(252,Math.pow(Math.max(0,lum)/255,0.84)*246+10);const scale=lum>1?boostedLum/lum:1;sr=boostedLum+(sr*scale-boostedLum)*1.28;sg=boostedLum+(sg*scale-boostedLum)*1.28;sb=boostedLum+(sb*scale-boostedLum)*1.28;const isBoundary=maskMap[(y-1)*size+x]===0||maskMap[(y+1)*size+x]===0||maskMap[rowOff+(x-1)]===0||maskMap[rowOff+(x+1)]===0;if(isBoundary){sr=Math.min(255,sr*1.15+18);sg=Math.min(255,sg*1.15+18);sb=Math.min(255,sb*1.15+22);}data[i]=Math.max(0,Math.min(255,Math.round(sr)));data[i+1]=Math.max(0,Math.min(255,Math.round(sg)));data[i+2]=Math.max(0,Math.min(255,Math.round(sb)));data[i+3]=255;}}context.putImageData(image,0,0);if(tissueCount>30){const bw=Math.max(16,maxX-minX+1);const bh=Math.max(16,maxY-minY+1);const maxDim=Math.max(bw,bh);const targetSpan=size*0.82;const scaleFactor=Math.max(0.85,Math.min(2.6,targetSpan/maxDim));const boxCenterX=(minX+maxX)*0.5;const boxCenterY=(minY+maxY)*0.5;if(Math.abs(scaleFactor-1)>0.05||Math.hypot(boxCenterX-size*0.5,boxCenterY-size*0.5)>size*0.025){const tempCanvas=document.createElement("canvas");tempCanvas.width=size;tempCanvas.height=size;const tempCtx=tempCanvas.getContext("2d");if(tempCtx){tempCtx.drawImage(canvas,0,0);const bgGrad=context.createRadialGradient(size*0.5,size*0.5,size*0.08,size*0.5,size*0.5,size*0.56);bgGrad.addColorStop(0,"#101726");bgGrad.addColorStop(0.65,"#090d16");bgGrad.addColorStop(1,"#05070c");context.fillStyle=bgGrad;context.fillRect(0,0,size,size);context.save();context.imageSmoothingEnabled=true;context.imageSmoothingQuality="high";context.translate(size*0.5,size*0.5);context.scale(scaleFactor,scaleFactor);context.translate(-boxCenterX,-boxCenterY);context.drawImage(tempCanvas,0,0);context.restore();}}}context.save();const fontPx=Math.max(12,Math.round(size*0.024));context.font=`700 ${fontPx}px ui-monospace, SFMono-Regular, Menlo, monospace`;context.fillStyle="rgba(148, 163, 184, 0.72)";context.textAlign="center";context.textBaseline="top";context.fillText("A (Anterior)",size/2,Math.round(size*0.016));context.textBaseline="bottom";context.fillText("P (Posterior)",size/2,Math.round(size*0.984));context.textBaseline="middle";context.textAlign="left";context.fillText("R",Math.round(size*0.02),size/2);context.textAlign="right";context.fillText("L",Math.round(size*0.98),size/2);context.restore();last=context.getImageData(0,0,size,size);}
let last:ImageData|null=null;
function fit(canvas:HTMLCanvasElement,size:number):void{if(canvas.width!==size)canvas.width=size;if(canvas.height!==size)canvas.height=size;}
export function restoreSlice(canvas:HTMLCanvasElement):void{if(!last)return;fit(canvas,last.width);const context=canvas.getContext("2d");context?.putImageData(last,0,0);}
export function forgetSlice():void{last=null;}
