export function getPdfClinicalScanDataUrl(caseId:string,modality?:string):string{const cleanId=(caseId||"").trim();if(PDF_CLINICAL_SCAN_DATA_URLS[cleanId]){return PDF_CLINICAL_SCAN_DATA_URLS[cleanId]!;}const mappedKey=CASE_TO_PDF_SCAN_KEY[cleanId];if(mappedKey&&PDF_CLINICAL_SCAN_DATA_URLS[mappedKey]){return PDF_CLINICAL_SCAN_DATA_URLS[mappedKey]!;}if(cleanId.includes("normal")){if(cleanId.includes("brain")||modality==="neuro_ct")return PDF_CLINICAL_SCAN_DATA_URLS.ct_brain_normal!;if(cleanId.startsWith("ct_"))return PDF_CLINICAL_SCAN_DATA_URLS.ct_chest_normal!;if(cleanId.startsWith("cxr_")||modality==="chest_xray")return PDF_CLINICAL_SCAN_DATA_URLS.cxr_normal!;if(cleanId.startsWith("echo_")||modality==="echo")return PDF_CLINICAL_SCAN_DATA_URLS.echo_normal!;return PDF_CLINICAL_SCAN_DATA_URLS.abd_normal!;}if(cleanId.startsWith("cxr_"))return PDF_CLINICAL_SCAN_DATA_URLS.cxr_pneumonia!;if(cleanId.startsWith("ct_brain")||cleanId.startsWith("ct_ischemic")||cleanId.startsWith("ct_trauma")||cleanId.startsWith("ct_hydro")||modality==="neuro_ct"){return PDF_CLINICAL_SCAN_DATA_URLS.ct_brain_hemorrhage!;}if(cleanId.startsWith("ct_"))return PDF_CLINICAL_SCAN_DATA_URLS.ct_pneumonia_infection!;if(cleanId.startsWith("card_")||cleanId.startsWith("echo_")||modality==="echo"){return PDF_CLINICAL_SCAN_DATA_URLS.echo_heart_failure!;}return PDF_CLINICAL_SCAN_DATA_URLS.liv_fatty_steatosis!;}
